/* eslint-env jest */
'use strict';

const os = require('os');
const _ = require('lodash');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Secure Cookie', () => {
    let logger;
    let stdout;
    let baseRecord;

    beforeEach(() => {
        // Jest's way to mock stdout.write
        stdout = { write: jest.fn() };

        // Use Jest to mock timers
        jest.useFakeTimers();

        // Set up the clock to the fake time
        jest.setSystemTime(1000);

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };
    });

    afterEach(() => {
        // Clear all mocked timers
        jest.clearAllTimers();
    });

    it('должен обфусцировать cookie в виде строки из req.headers.cookie', () => {
        logger = getLogger({
            cookies: ['str', 'number', 'empty'],
        });

        let req = {
            headers: {
                host: 'yandex.ru',
                cookie: 'yandexuid=123; str=value; number=123; empty=; sk=asdasd',
            },
        };
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stdout.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                headers: {
                    host: 'yandex.ru',
                    cookie: 'yandexuid=123; str=vaXXX; number=1XX; empty=; sk=asdasd',
                },
            },
        });
        expect(stdout.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('не должен копировать заголовки, если значение cookie не изменилось', () => {
        logger = getLogger({
            cookies: ['empty'],
        });

        let req = {
            headers: {
                host: 'yandex.ru',
                cookie: 'yandexuid=123; str=value; number=123; empty=; sk=asdasd',
            },
        };
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stdout.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                headers: {
                    host: 'yandex.ru',
                    cookie: 'yandexuid=123; str=value; number=123; empty=; sk=asdasd',
                },
            },
        });
        expect(stdout.write).toHaveBeenCalledTimes(1);

        expect(stdout.write.mock.calls[0][0].req).toBe(req);
        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен обфусцировать cookie в виде объекта из req.cookies', () => {
        logger = getLogger({
            field: 'req.cookies',
            cookies: ['str', 'number', 'obj', 'empty'],
        });

        let req = {
            cookies: {
                yandexuid: '123',
                str: 'value',
                number: 123,
                obj: {},
                empty: '',
                sk: 'asdasd',
            },
        };
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stdout.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                cookies: {
                    yandexuid: '123',
                    str: 'vaXXX',
                    number: 123,
                    obj: {},
                    empty: '',
                    sk: 'asdasd',
                },
            },
        });
        expect(stdout.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('не должен падать с req.cookies == null', () => {
        logger = getLogger({
            field: 'req.cookies',
            cookies: ['str'],
        });

        let req = {
            cookies: null,
        };
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stdout.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                cookies: null,
            },
        });
        expect(stdout.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен использовать функцию обфускации из конфига', () => {
        logger = getLogger({
            field: 'req.cookies',
            cookies: ['str'],
            secureValue(value) {
                return `${value}-secured!`;
            },
        });

        let req = {
            cookies: {
                yandexuid: '123',
                str: 'value',
            },
        };
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stdout.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                cookies: {
                    yandexuid: '123',
                    str: 'value-secured!',
                },
            },
        });
        expect(stdout.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен работать без конфига', () => {
        logger = getLogger();

        let req = {
            headers: {
                host: 'yandex.ru',
                cookie: 'yandexuid=123; str=value',
            },
            cookies: {
                yandexuid: '123',
                str: 'value',
            },
        };
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stdout.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                headers: {
                    host: 'yandex.ru',
                    cookie: 'yandexuid=123; str=value',
                },
                cookies: {
                    yandexuid: '123',
                    str: 'value',
                },
            },
        });
        expect(stdout.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    function getLogger(config) {
        return yandexLogger({
            streams: [
                { stream: stdout },
            ],
            middleware: [
                require('../../middleware/secure-cookie')(config),
            ],
        });
    }
});
